//! Word forms laid out as paradigm tables: a verb's principal parts, a noun's
//! plural, an adjective's degrees. Everything shown comes from the forms the
//! dictionary stores (nothing is generated by rule), so an irregular word is as
//! irregular here as in Wiktionary.

use serde::Serialize;

use crate::entry::{Block, Entry, Form};

#[derive(Debug, Clone, PartialEq, Serialize)]
pub struct Paradigm {
    pub pos: String,
    /// The dictionary's own inflection line, e.g. "abate (third-person singular simple present abates, ...)".
    #[serde(skip_serializing_if = "Option::is_none")]
    pub head: Option<String>,
    pub rows: Vec<Row>,
    /// Why a row is empty or incomplete.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub note: Option<String>,
}

#[derive(Debug, Clone, PartialEq, Serialize)]
pub struct Row {
    pub label: &'static str,
    /// Empty when the dictionary has no such form (shown as a dash).
    pub forms: Vec<Cell>,
}

#[derive(Debug, Clone, PartialEq, Serialize)]
pub struct Cell {
    pub form: String,
    /// "archaic", "nonstandard", ... when the form is not the ordinary one.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub note: Option<String>,
}

/// Tags that say which slot a form fills; any other tag is a usage label on the form.
const STRUCTURAL: &[&str] = &[
    "infinitive", "present", "past", "participle", "singular", "plural", "third-person", "first-person",
    "second-person", "comparative", "superlative", "subjunctive", "imperative",
];

const VERB: &[&str] = &["Base form", "Third person singular", "Present participle (-ing)", "Past", "Past participle"];
const NOUN: &[&str] = &["Singular", "Plural"];
const DEGREES: &[&str] = &["Positive", "Comparative", "Superlative"];

/// The row a form belongs in, and how exact the match is (0 exact, 1 a fallback used only when nothing exact exists).
fn slot(pos: &str, tags: &[String]) -> Option<(usize, u8)> {
    let has = |t: &str| tags.iter().any(|x| x == t);
    if has("alternative") || has("inflection-template") || has("imperative") || has("subjunctive") {
        return None;
    }
    match pos {
        "verb" if has("infinitive") => Some((0, 0)),
        "verb" if has("participle") && has("present") => Some((2, 0)),
        "verb" if has("participle") && has("past") => Some((4, 0)),
        "verb" if has("present") && has("singular") && has("third-person") => Some((1, 0)),
        "verb" if has("past") && !has("participle") => {
            let person = has("first-person") || has("second-person") || has("third-person") || has("singular") || has("plural");
            // "was" is only one of the past forms of "be"; it still beats showing nothing.
            if !person { Some((3, 0)) } else if has("third-person") && has("singular") { Some((3, 1)) } else { None }
        }
        "noun" if has("plural") => Some((1, 0)),
        "adj" | "adv" if has("comparative") => Some((1, 0)),
        "adj" | "adv" if has("superlative") => Some((2, 0)),
        _ => None,
    }
}

fn note_of(f: &Form) -> Option<String> {
    let extra: Vec<&str> = f.tags.iter().map(String::as_str).filter(|t| !STRUCTURAL.contains(t)).collect();
    (!extra.is_empty()).then(|| extra.join(", "))
}

fn labels(pos: &str) -> Option<&'static [&'static str]> {
    match pos {
        "verb" => Some(VERB),
        "noun" => Some(NOUN),
        "adj" | "adv" => Some(DEGREES),
        _ => None,
    }
}

/// A block that only says "inflected form of X" belongs to X's table, not its own.
fn is_inflected_entry(b: &Block) -> bool {
    !b.senses.is_empty() && b.senses.iter().all(|s| s.form_of.is_some())
}

/// The lemmas an entry's inflected-form senses point at ("went" -> "go"), once each.
pub fn lemmas_of(e: &Entry) -> Vec<String> {
    let mut out: Vec<String> = Vec::new();
    for s in e.blocks.iter().flat_map(|b| &b.senses) {
        if let Some(l) = s.form_of.as_deref().map(str::trim).filter(|l| !l.is_empty()) {
            if !out.iter().any(|x| x == l) {
                out.push(l.to_string());
            }
        }
    }
    out
}

/// One table per part of speech the word inflects in (verb, noun, adjective, adverb).
pub fn paradigms(word: &str, blocks: &[Block]) -> Vec<Paradigm> {
    let mut out: Vec<Paradigm> = Vec::new();
    // `rank[i][r]`: the best match quality seen so far for each row, so a fallback never sits beside an exact form.
    let mut best: Vec<Vec<u8>> = Vec::new();
    for b in blocks {
        let Some(names) = labels(&b.pos) else { continue };
        // Proper names ("Abate") and case variants have their own forms and are not this word's.
        if b.word.is_some() || b.pos == "name" || is_inflected_entry(b) {
            continue;
        }
        let at = match out.iter().position(|p| p.pos == b.pos) {
            Some(i) => i,
            None => {
                out.push(Paradigm {
                    pos: b.pos.clone(),
                    head: None,
                    rows: names.iter().map(|&label| Row { label, forms: Vec::new() }).collect(),
                    note: None,
                });
                best.push(vec![u8::MAX; names.len()]);
                out.len() - 1
            }
        };
        if out[at].head.is_none() {
            out[at].head = b.head.clone();
        }
        for f in &b.forms {
            let Some((r, q)) = slot(&b.pos, &f.tags) else { continue };
            if q > best[at][r] {
                continue;
            }
            if q < best[at][r] {
                best[at][r] = q;
                out[at].rows[r].forms.clear();
            }
            let cells = &mut out[at].rows[r].forms;
            if !cells.iter().any(|c| c.form == f.form) {
                cells.push(Cell { form: f.form.clone(), note: note_of(f) });
            }
        }
    }
    for p in &mut out {
        // The ordinary form first, then the archaic and nonstandard ones.
        for r in &mut p.rows {
            r.forms.sort_by_key(|c| c.note.is_some());
        }
        if p.rows[0].forms.is_empty() {
            p.rows[0].forms.push(Cell { form: word.to_string(), note: None });
        }
        let said = p.head.as_deref().unwrap_or("").to_lowercase();
        p.note = match p.pos.as_str() {
            "noun" if p.rows[1].forms.is_empty() && said.contains("uncountable") => Some("Uncountable: no plural.".into()),
            "adj" | "adv" if p.rows[1].forms.is_empty() && p.rows[2].forms.is_empty() && said.contains("not comparable") => Some("Not comparable.".into()),
            "verb" if said.contains("irregular") && p.rows.iter().any(|r| r.forms.is_empty()) => {
                Some("A very irregular verb: Wiktionary gives it a long conjugation table, and only part of it is kept in this copy of the dictionary.".into())
            }
            _ => None,
        };
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::entry::Sense;

    fn form(f: &str, tags: &[&str]) -> Form {
        Form { form: f.into(), tags: tags.iter().map(|t| t.to_string()).collect() }
    }
    fn block(pos: &str, head: &str, forms: Vec<Form>) -> Block {
        Block { pos: pos.into(), head: Some(head.into()), forms, senses: vec![Sense { gloss: "x".into(), ..Default::default() }], ..Default::default() }
    }
    fn row<'a>(p: &'a Paradigm, label: &str) -> Vec<&'a str> {
        p.rows.iter().find(|r| r.label == label).unwrap().forms.iter().map(|c| c.form.as_str()).collect()
    }

    #[test]
    fn a_verb_gets_its_principal_parts() {
        let b = block("verb", "go (...)", vec![
            form("goes", &["present", "singular", "third-person"]),
            form("going", &["participle", "present"]),
            form("went", &["past"]),
            form("goed", &["nonstandard", "past"]),
            form("gone", &["participle", "past"]),
            form("glossary", &["inflection-template"]),
            form("go", &["first-person", "present", "singular"]),
        ]);
        let p = &paradigms("go", &[b])[0];
        assert_eq!(row(p, "Base form"), ["go"]);
        assert_eq!(row(p, "Third person singular"), ["goes"]);
        assert_eq!(row(p, "Present participle (-ing)"), ["going"]);
        assert_eq!(row(p, "Past"), ["went", "goed"]);
        assert_eq!(p.rows[3].forms[1].note.as_deref(), Some("nonstandard"));
        assert_eq!(row(p, "Past participle"), ["gone"]);
        assert!(p.note.is_none());
    }

    #[test]
    fn the_same_part_of_speech_in_two_blocks_is_one_table() {
        let a = block("verb", "abate", vec![form("abates", &["present", "singular", "third-person"]), form("abated", &["past"])]);
        let again = a.clone();
        let ps = paradigms("abate", &[a, again]);
        assert_eq!(ps.len(), 1);
        assert_eq!(row(&ps[0], "Third person singular"), ["abates"]);
    }

    #[test]
    fn nouns_and_adjectives_and_their_notes() {
        let n = block("noun", "sheep (uncountable)", vec![]);
        let a = block("adj", "loquacious (comparative more loquacious, superlative most loquacious)", vec![form("more loquacious", &["comparative"]), form("most loquacious", &["superlative"])]);
        let c = block("adj", "unique (not comparable)", vec![]);
        let ps = paradigms("sheep", &[n]);
        assert_eq!(ps[0].note.as_deref(), Some("Uncountable: no plural."));
        assert_eq!(row(&ps[0], "Singular"), ["sheep"]);
        let ps = paradigms("loquacious", &[a]);
        assert_eq!(row(&ps[0], "Comparative"), ["more loquacious"]);
        assert_eq!(row(&ps[0], "Superlative"), ["most loquacious"]);
        assert_eq!(paradigms("unique", &[c])[0].note.as_deref(), Some("Not comparable."));
    }

    #[test]
    fn a_fallback_past_never_sits_beside_an_exact_one() {
        let be = block("verb", "be (highly irregular—See conjugation table)", vec![
            form("be", &["infinitive"]),
            form("was", &["past", "singular", "third-person"]),
        ]);
        let p = &paradigms("be", &[be])[0];
        assert_eq!(row(p, "Past"), ["was"]);
        assert!(p.note.as_deref().unwrap().contains("irregular"));
        let exact = block("verb", "x", vec![form("was", &["past", "singular", "third-person"]), form("done", &["past"])]);
        assert_eq!(row(&paradigms("x", &[exact])[0], "Past"), ["done"]);
    }

    #[test]
    fn inflected_entries_and_names_are_skipped_and_point_at_their_lemma() {
        let went = Block {
            pos: "verb".into(),
            senses: vec![Sense { gloss: "simple past of go".into(), form_of: Some("go".into()), ..Default::default() }],
            ..Default::default()
        };
        let name = Block { pos: "name".into(), forms: vec![form("Abates", &["plural"])], senses: vec![Sense::default()], ..Default::default() };
        assert!(paradigms("went", &[went.clone(), name]).is_empty());
        let e = Entry { word: "went".into(), blocks: vec![went], ..Default::default() };
        assert_eq!(lemmas_of(&e), ["go"]);
    }
}
